import {h,icon,button as btn,plural} from './ui.mjs';
import {renderIllustration} from './illustrations.mjs';
import {getReviewFor} from './memory.mjs';

export const reviewTime=value=>new Date(value).toLocaleString('ru-RU',{timeZone:'Europe/Copenhagen',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});

export function renderMemoryPlan({memoryPlan:p}){
 const ready=p.items.length>0;
 return `<section class="memory-plan panel"><div class="memory-plan-copy"><span class="eyebrow">НЕБОЛЬШАЯ ПРАКТИКА · ДОЛГАЯ ПАМЯТЬ</span><h2>Вспомнить, а не просто узнать.</h2><p>${p.dueTotal?`Пора вернуться к ${p.dueTotal} ${plural(p.dueTotal,['заданию','заданиям','заданиям'])}. Сначала повторение, затем новое.`:p.newCount?'Познакомься с новым, затем проверь себя без открытой карточки.':p.nextDue?`Ближайшая проверка — ${reviewTime(p.nextDue)} по времени Дании.`:'Новых заданий на сегодня достаточно. Можно продолжить обычный урок.'}</p><div class="memory-plan-actions">${ready?btn(`Практика памяти ${icon('arrow')}`,'start-memory'):btn('Открыть уроки','start-next','secondary')}<button class="text-button" data-page="method">Как это работает ${icon('info')}</button></div></div><div class="memory-batch"><div><span class="memory-batch-icon">${icon('repeat')}</span><b>${p.dueCount}</b><span>повторить сейчас</span></div><div><span class="memory-batch-icon mint">${icon('plus')}</span><b>${p.newCount}</b><span>${p.newCount===1?'новое':'новых'} в наборе</span></div><small>Новое сегодня: ${p.newToday} / ${p.newLimit}<br>До 6 заданий в одном наборе</small></div></section>`;
}

export function renderMemoryStats({memorySummary:s}){
 return `<section class="memory-progress"><div class="section-title"><div><h2>Что получилось вспомнить</h2><p>Проверенные задания, без дублей. Один пункт может входить в несколько показателей.</p></div></div><div class="memory-stats">${[[s.recognized,'Узнал среди вариантов','cards','blue'],[s.recalled,'Вспомнил без вариантов','brain','purple'],[s.retained,'Вспомнил в разные дни','repeat','mint'],[s.transferred||0,'Применил в разных контекстах','chat','peach']].map(([n,label,ic,tone])=>`<article class="panel memory-stat ${tone}"><span>${icon(ic)}</span><b>${n}</b><h3>${label}</h3></article>`).join('')}</div><p class="field-note">«В разные дни» требует ещё двух успешных самостоятельных повторений: каждое по расписанию и не раньше чем через сутки после предыдущего. Подсказки и немедленные исправления сюда не входят. «В разных контекстах» — два разных авторских предложения, успешно дополненных по расписанию в разные дни. Старые ответы сохранены, но их тип нельзя определить задним числом.</p></section>`;
}

export function renderStudy(session,catalog){
 return `<main class="session-shell"><header class="session-header"><button class="icon-button" data-action="pause-request" title="Сохранить и выйти">${icon('close')}</button><div class="session-meter"><span>${h(session.title)} · знакомство</span></div><span class="pill mint">${session.studyIds.length} ${session.studyIds.length===1?'новое':'новых'}</span></header><section class="memory-study"><span class="eyebrow">ПОСМОТРИ · ПРЕДСТАВЬ · ПРОИЗНЕСИ</span><h1>Сначала познакомимся.</h1><p>Прочитай смысл, представь ситуацию и произнеси датскую фразу. Дальше эти карточки закроются.</p><div class="memory-study-grid">${session.studyIds.map(id=>{const p=catalog[id];return `<article class="panel memory-study-card">${renderIllustration(p)}<div class="memory-study-word"><h2 lang="da">${h(p.da)}</h2><button class="icon-button" data-action="speak" data-id="${h(id)}" title="Послушать">${icon('sound')}</button></div><p class="detail-translation">${h(p.ru)}</p>${p.exampleDa?`<div class="word-example"><p lang="da">${h(p.exampleDa)}</p><small>${h(p.exampleRu||'')}</small></div>`:''}${p.note?`<p class="study-note">${h(p.note)}</p>`:''}${p.association?`<div class="association">${icon('brain')}<p>${h(p.association)}</p></div>`:''}</article>`;}).join('')}</div><p class="field-note">Не нужно запоминать всё за один просмотр. Ассоциация — опора для смысла, а не точная подсказка к произношению.</p>${btn(`Попробовать вспомнить ${icon('arrow')}`,'study-start')}</section></main>`;
}

export function renderMemoryResult(session,state){
 const outcomes=(session.outcomes||[]).filter(o=>!o.retry),independent=outcomes.filter(o=>o.correct&&!o.helped&&o.kind==='recall').length,recognized=outcomes.filter(o=>o.correct&&!o.helped&&o.kind==='recognition').length,helped=outcomes.filter(o=>o.helped).length;
 const dues=[...new Set(outcomes.map(o=>o.itemId))].map(id=>getReviewFor({id},state.reviews)?.due).filter(Number.isFinite);
 return `<div class="memory-result panel"><h3>Как ты отвечал</h3><p><b>${independent}</b> без вариантов · <b>${recognized}</b> с вариантами или сборкой${helped?` · <b>${helped}</b> с подсказкой`:''}</p><small>${dues.length?`Ближайшая проверка этих заданий: ${reviewTime(Math.min(...dues))} по времени Дании.`:'Следующая практика появится в повторении.'} Ответ сразу после знакомства ещё не подтверждает долговременную память. Самопроверка другой формулировки не добавляет XP и подтверждённых самостоятельных ответов.</small></div>`;
}

export function renderMethod(){
 const steps=[['cards','blue','01','Понять смысл','Небольшая порция нового: перевод, ситуация, пример и произношение, если на устройстве установлен датский голос. Для выражений учи целую конструкцию: например, holde af + человек или предмет.'],['brain','purple','02','Попытаться вспомнить','Сначала выбор ответа. После успеха — сборка длинной фразы, затем ввод без вариантов. Затем слово нужно вставить в предложение. Для 30 повседневных слов чередуются два новых контекста и явно заданные формы.'],['chat','peach','03','Разобрать и применить','После ответа открыт разбор. Ошибка возвращается один раз в конце занятия. Произнеси свою короткую фразу или измени одну деталь примера: это отдельная практика речи без автоматической оценки.'],['repeat','mint','04','Вернуться спустя время','Ответ с вариантами не отправляет слово сразу на недельный интервал. Самостоятельное воспроизведение продвигает повторение дальше; ошибка или подсказка возвращает короткий интервал.']];
 return `<div class="page-heading"><div><h1>Как устроена практика памяти</h1><p>Понять → вспомнить → применить → вернуться.</p></div></div><div class="memory-method-grid">${steps.map(([ic,tone,n,title,text])=>`<article class="panel memory-method-card ${tone}"><div><span>${icon(ic)}</span><b>${n}</b></div><h2>${title}</h2><p>${text}</p></article>`).join('')}</div><section class="panel method-detail"><h2>Нагрузка под контролем</h2><p>В наборе до шести заданий: сначала подошедшие повторения, затем не больше двух новых. Дневной предел нового — 3, 6 или 10, его можно изменить в настройках. Знакомые задания заранее не добавляются для заполнения набора. Значения одного многозначного слова не вводятся одновременно.</p><p>Ручные отметки и личные слова получают приоритет; грамматика чередуется с другими типами материала, когда они доступны. Уровень сложности выбираешь ты. Уроки и ручные режимы доступны отдельно от дневного плана.</p><button class="text-button" data-page="settings">Настроить нагрузку ${icon('arrow')}</button></section><section class="panel method-detail"><h2>Что именно учитывается</h2><p>Выбор и сборка учитываются как ответ с опорой. Ввод правильного ответа без вариантов, подсказки и показа текста — как самостоятельное вспоминание. Исправление в конце того же занятия помогает учиться, но не доказывает, что материал удержался спустя время.</p><div class="spacing-steps"><span class="peach">Ошибка / подсказка · 10 мин</span><span class="blue">Первое узнавание · 10 мин</span><span>Вспомнил сам · адаптивно, от 1 до 90 дней</span></div><p>Долгий интервал рассчитывается по FSRS-6: учитываются предыдущие самостоятельные ответы, ошибки и время с последней проверки. Используются общие параметры модели и целевое удержание 90%, а не персонально обученные параметры. Ограничение 1–90 дней и короткий повтор через 10 минут — настройки приложения. Расчёт не гарантирует вероятность запоминания конкретному человеку. Результат в карточках также не измеряет свободную разговорную речь.</p></section><section class="panel method-detail"><h2>Произносить и сверять</h2><p>Послушай образец, повтори по частям, произнеси целиком и сравни со своей записью. В каждом упражнении — одна конкретная особенность: гласный, мягкое d, ударение или ритм. Самооценка не прибавляет XP. Один синтезированный голос не заменяет живые голоса разных людей.</p><button class="text-button" data-page="pronunciation">Практика произношения</button></section><section class="panel method-detail"><h2>На чём основан подход</h2><p>Исследования поддерживают повторное извлечение из памяти и распределение практики во времени. Тренировка узнавания и самостоятельного воспроизведения развивает разные стороны знания слова. Поэтому в приложении есть оба вида заданий и раздельный учёт результатов.</p><div class="method-sources"><a href="https://github.com/open-spaced-repetition/awesome-fsrs/wiki/The-Algorithm" target="_blank" rel="noopener noreferrer">FSRS-6 · модель интервалов</a><a href="https://pubmed.ncbi.nlm.nih.gov/40106429/" target="_blank" rel="noopener noreferrer">Yao et al., 2025 · метаанализ фонетической тренировки</a><a href="https://doi.org/10.1126/science.1152408" target="_blank" rel="noopener noreferrer">Karpicke & Roediger, 2008 · попытки вспомнить ${icon('external')}</a><a href="https://doi.org/10.1017/S0272263114000825" target="_blank" rel="noopener noreferrer">Nakata, 2015 · интервалы повторения ${icon('external')}</a><a href="https://doi.org/10.1177/0033688209343854" target="_blank" rel="noopener noreferrer">Webb, 2009 · узнавание и воспроизведение ${icon('external')}</a><a href="https://doi.org/10.1111/lang.12479" target="_blank" rel="noopener noreferrer">Kim & Webb, 2022 · метаанализ интервальной практики ${icon('external')}</a><a href="https://doi.org/10.1177/13621688211053525" target="_blank" rel="noopener noreferrer">Karatas et al., 2025 · повторение и попытки вспомнить ${icon('external')}</a><a href="https://doi.org/10.2167/illt039.0" target="_blank" rel="noopener noreferrer">Nation, 2007 · четыре направления практики ${icon('external')}</a></div><p>Дополняй задания понятным чтением и аудио, общением и собственными фразами. Эффективность именно Danskdag ещё не измерялась; приложение не обещает одинакового результата или «идеального» расписания для всех.</p></section>`;
}
